Mysql2::Error: Duplicate entry '18401233-Chapter-796508' for key 'creation_id_creation_type_pseud_id': INSERT INTO `creatorships` (`created_at`, `creation_id`, `creation_type`, `pseud_id`, `updated_at`) VALUES ('2016-09-14 11:56:33', 18401233, 'Chapter', 796508, '2016-09-14 11:56:33')
